/* ---- NEON ARCADE GLASSMORPHISM THEME ---- */
@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@700&family=Press+Start+2P&display=swap');

:root {
  --arcade-neon-turq: #19fff3;
  --arcade-neon-pink: #fd38fc;
  --arcade-neon-violet: #7d43fc;
  --arcade-dark-bg: #0d0d0d;
  --arcade-card-glass: rgba(26, 24, 38, 0.78);
  --arcade-bright: #fff1fc;
  --arcade-btn-bg: rgba(31,17,37, 0.62);
  --arcade-border: 2.1px solid rgba(122,255,244,0.18);

  --arcade-font: 'Orbitron', 'Press Start 2P', 'Arial Black', 'Arial', sans-serif;
  --arcade-title-shadow: 0 1px 10px #19fff355, 0 0 14px #fd38fc44, 0 0 6px #7d43fc66;
  --arcade-glow: 0 0 7px #fffbeea0, 0 0 18px #fd38fc88, 0 0 34px #19fff3a8;
}

/* BACKGROUND */
.mmarcade-bg {
  min-height: 100vh;
  width: 100vw;
  background: radial-gradient(ellipse at 65% 30%, #2400a750 35%, #19fff335 80%, transparent 100%),
    radial-gradient(ellipse at 35% 70%, #fd38fc33 35%, #0be8db25 65%, transparent 100%),
    linear-gradient(150deg, #0d0d0d 92%, #270045 100%);
  position: fixed;
  top: 0; left: 0;
  z-index: -1;
  animation: bgColorGlow 5s ease-in-out infinite alternate-reverse;
}

@keyframes bgColorGlow {
  from { filter: brightness(1) drop-shadow(0px 0px 28px #19fff355);}
  to   { filter: brightness(1.03) drop-shadow(0px 0px 52px #fd38fc66);}
}

.mmarcade-flex-center {
  min-height: 100vh; /* fill screen */
  display: flex;
  align-items: center;
  justify-content: center;
}

/* MAIN ARCADE CARD */
.mmarcade-card {
  background: var(--arcade-card-glass);
  box-shadow: 0 5px 28px 3px #19fff348, 0 1px 1.6px 0 #fd38fc33, 0 0 36px 10px #36175780;
  border-radius: 2.2rem;
  border: var(--arcade-border);
  padding: 2.5rem 1.7rem 1.7rem 1.7rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 430px;
  width: 96vw;
  margin: 0 1rem;
  transition: 0.27s box-shadow cubic-bezier(.57,.07,.47,1.64);
  font-family: var(--arcade-font);
  position: relative;
  overflow: visible;
}

.mmarcade-fadein {
  opacity: 0;
  transform: scale(1.02) translateY(24px);
  animation: mmarcade-fadein-anim .96s cubic-bezier(.85,.01,.49,1.06) 0s forwards;
}
@keyframes mmarcade-fadein-anim {
  to { opacity: 1; transform: none;}
}
.mmarcade-finish { opacity: 1;}

/* HEADER & LOGO */
.mmarcade-header {
  text-align: center;
  margin-bottom: 0.9rem;
}

.mmarcade-logoemoji {
  font-size: 2.7em;
  filter: drop-shadow(0 0 8px #fd38fc);
  margin-bottom: -0.2em;
  padding-bottom: 0.18em;
  display: inline-block;
  animation: arcade-titlepop 1.5s cubic-bezier(.13,1.62,.74,.93) 0.3s both;
}

@keyframes arcade-titlepop {
  0%   { transform: scale(0.6) rotate(-18deg); opacity: 0.15; }
  76%  { transform: scale(1.2) rotate(17deg); opacity: .98; }
  92%  { transform: scale(1.04) rotate(-3deg);}
  100% { transform: scale(1) rotate(0); opacity: 1;}
}

.mmarcade-title {
  font-family: var(--arcade-font);
  color: var(--arcade-bright);
  text-shadow: var(--arcade-title-shadow);
  font-size: 2.22em;
  margin: 0;
  padding-top: 0.12em;
  padding-bottom: 0.18em;
  letter-spacing: 0.066em;
}

.mmarcade-glowbar {
  margin: 0 auto;
  width: 62%;
  height: 7px;
  border-radius: 5px;
  background: linear-gradient(90deg,#19fff3 17%,#fd38fc 65%,#3617cc 95%);
  filter: blur(3px) brightness(1.5);
  box-shadow: 0 0 12px #fd38fc, 0 0 22px #19fff3;
  opacity: 0.62;
}

.mmarcade-blurb, .mmarcade-about {
  color: #fff6;
  font-size: 1.088em;
  margin-bottom: 0.9rem;
  text-align: center;
  line-height: 1.5;
}
.mmarcade-emph {
  font-family: 'Press Start 2P', 'Orbitron', Arial, sans-serif;
  color: #19fff3;
  text-shadow: 0 0 17px #fd38fc80;
  font-size: 1.03em;
  letter-spacing: 0.06em;
  margin-top: 2px;
}

.mmarcade-about > h2 {
  color: #fd38fc;
  text-shadow: 0 1px 10px #fd38fc, 0 0 10px #19fff3;
  font-size: 1.16em;
  margin-bottom: 0.44em;
}

.mmarcade-divider {
  margin: 1.06rem auto 0.54rem;
  background: linear-gradient(87deg, #19fff3 12%, #fd38fc 55%, #3617cc 100%);
  height: 2px;
  width: 70%;
  border-radius: 2px;
  opacity: 0.80;
  box-shadow: 0 1px 10px #19fff355, 0 0 15px #fd38fc22;
}

/* FUN EXTRAS: JOKE / QUOTE / FACT */
.mmarcade-funextras-grid {
  display: flex;
  gap: 0.9rem;
  width: 100%;
  justify-content: center;
  flex-wrap: wrap;
}

.mmarcade-glassbox {
  flex: 1 1 100px;
  min-width: 0;
  background: rgba(36, 16, 57, 0.45);
  border: 1.3px solid #19fff3bb;
  box-shadow: 0 0 11px #fd38fc22, 0 0 18px #19fff322;
  border-radius: 1.07em;
  padding: 0.93em 0.83em 0.82em;
  max-width: 214px;
  margin-bottom: 0.5em;
}

.mmarcade-fun-title {
  color: #fff;
  font-family: 'Orbitron', 'Press Start 2P', Arial, sans-serif;
  font-size: 1.085em;
  margin-bottom: 0.33em;
  letter-spacing: 0.02em;
  text-shadow: 0 0 6px #19fff3aa, 0 0 11px #fd38fc66;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.12em;
}
.mmarcade-fun-content {
  color: #daf7fd;
  font-size: 1em;
  text-shadow: 0 1.5px 8px #19fff388;
  word-break: break-word;
  white-space: pre-line;
  margin-bottom: 0.15em;
}
.mmarcade-fun-author {
  color: #fd38fc;
  text-shadow: 0 0 5px #7d43fc, 0 0 10px #fffbeea0;
  font-size: 0.88em;
  margin-left: 7px;
}

.mmarcade-err {
  color: #f85b9c !important;
  text-shadow: 0 0 3px #fd38fc, 0 0 8px #fffaf6bb;
}

/* REFRESH BUTTON inside title - glassy, round, neon */
.mmarcade-refresh {
  border: none;
  background: var(--arcade-btn-bg);
  color: #19fff3;
  font-size: 1.15em;
  padding: 0.17em 0.32em;
  margin-left: .4em;
  border-radius: 1.9em;
  box-shadow: 0 0 9px #19fff366, 0 0 3px #fd38fcbb;
  transition: background .18s, box-shadow .19s;
  outline: none;
  cursor: pointer;
}
.mmarcade-refresh:hover,
.mmarcade-refresh:focus {
  background: #19fff343;
  color: #fd38fc;
  box-shadow: 0 0 19px #fd38fcbb, 0 0 15px #19fff3;
}

/* RESPONSIVE media queries */
@media (max-width: 650px) {
  .mmarcade-card {
    padding: 1.3rem 0.4rem 1.15rem 0.4rem;
    max-width: 99vw;
    border-radius: 1.36em;
  }
  .mmarcade-funextras-grid {
    flex-direction: column;
    gap: .73rem;
  }
  .mmarcade-glassbox {
    max-width: unset;
    width: 98%;
    padding-left: 0.3em;
    padding-right: 0.3em;
  }
}
@media (max-width: 410px) {
  .mmarcade-title { font-size: 1.19em; }
  .mmarcade-header { margin-bottom: 0.4em;}
  .mmarcade-blurb, .mmarcade-about { font-size: 0.91em;}
}

